    // wocc_sky codegen contract test (Phase 7b)
    // Validates the SPIRV-Reflect -> C++ header codegen pipeline end-to-end:
    //   1. Generated struct sizeof + offset constants match expectations.
    //   2. SPV decoration: viewProjection is RowMajor (not ColMajor) per
    //      AGENTS.md matrix layout hard constraint.
    //   3. codegen constants cross-check against .reflection.yaml member
    //      offsets (loaded via fkYAML) so the header and the YAML are
    //      guaranteed to come from the same SPV reflection.
    // ----------------------------------------------------------------
    {
        constexpr uint32_t spirvDecorationRowMajor = 4u;
        constexpr uint32_t spirvDecorationColMajor = 5u;

        // (1) Generated header layout contract (wocc_sky.shader_bindings.h).
        // Source of truth is spirv-reflect on wocc_sky.spv; the static_assert
        // in the generated header already guards sizeof, here we also check
        // the named offset constants.
        static_assert(sizeof(arp::shader::gen::WoccSkyPushConstants) == 144,
            "wocc_sky codegen: struct size must match SPV push-constant block");
        static_assert(arp::shader::gen::kWoccSkyPushConstantsSize == 144, "");
        static_assert(arp::shader::gen::kWoccSkyPushConstantsViewProjectionOffset == 0, "");
        static_assert(arp::shader::gen::kWoccSkyPushConstantsCameraXzDomeRadiusOffset == 64, "");
        static_assert(arp::shader::gen::kWoccSkyPushConstantsSunDirSunColorROffset == 80, "");
        static_assert(arp::shader::gen::kWoccSkyPushConstantsZenithBExposureOffset == 128, "");

        // (2) SPV decoration on wocc_sky.spv: viewProjection must be RowMajor.
        const auto woccSkySpirv = readBinaryFile("shaders/wocc_sky.spv");
        assert(!woccSkySpirv.empty());
        assert(spirvMemberHasDecoration(woccSkySpirv,
            "WoccSkyPushConstants_std430",
            "viewProjection",
            spirvDecorationColMajor));
        assert(!spirvMemberHasDecoration(woccSkySpirv,
            "WoccSkyPushConstants_std430",
            "viewProjection",
            spirvDecorationRowMajor));

        // (3) Cross-check: load wocc_sky.reflection.yaml via fkYAML and verify
        // the member offsets match the codegen header constants exactly.
        // This proves the YAML, the header, and the SPV all agree.
        const std::pmr::string skyYamlCandidates[] = {
            "shaders/wocc_sky.reflection.yaml",
            "artifacts/direct/shaders/wocc_sky.reflection.yaml",
            "../shaders/wocc_sky.reflection.yaml",
            "../artifacts/direct/shaders/wocc_sky.reflection.yaml",
            "../../shaders/wocc_sky.reflection.yaml",
            "../../artifacts/direct/shaders/wocc_sky.reflection.yaml",
            joinedPath(
                ARP_SHADER_TEST_SOURCE_DIR, std::pmr::string("shaders/wocc_sky.reflection.yaml")),
            joinedPath(
                ARP_SHADER_TEST_BINARY_DIR, std::pmr::string("shaders/wocc_sky.reflection.yaml")),
        };
        std::pmr::string skyYaml;
        for (const auto& c : skyYamlCandidates) {
            std::ifstream rf(c.c_str());
            if (rf.good()) {
                skyYaml.assign(
                    std::istreambuf_iterator<char>(rf), std::istreambuf_iterator<char>());
                break;
            }
        }
        assert(!skyYaml.empty());
        const auto skyReflection = arp::shader::ShaderReflectionCache::loadFromYaml(skyYaml);
        assert(skyReflection.success);
        assert(skyReflection.module.moduleName == std::pmr::string("WoccSky"));
        assert(skyReflection.module.reflection.pushConstantSizeBytes
            == arp::shader::gen::kWoccSkyPushConstantsSize);
        // Member-level layout must be present (emitted by shader_bindings_codegen.py).
        assert(skyReflection.module.reflection.pushConstantMembers.size() == 6);

        // First member is viewProjection (matrix, RowMajor, offset 0, size 64).
        const auto& vpMember = skyReflection.module.reflection.pushConstantMembers[0];
        assert(vpMember.name == std::pmr::string("viewProjection"));
        assert(vpMember.offset == arp::shader::gen::kWoccSkyPushConstantsViewProjectionOffset);
        assert(vpMember.size == 64);
        assert(vpMember.matrixRows == 4);
        assert(vpMember.matrixCols == 4);
        assert(vpMember.matrixStride == 16);
        assert(vpMember.rowMajor == true);

        // The remaining 5 members are float4 vectors at 16-byte strides.
        assert(skyReflection.module.reflection.pushConstantMembers[1].name
            == std::pmr::string("cameraXzDomeRadius"));
        assert(skyReflection.module.reflection.pushConstantMembers[1].offset
            == arp::shader::gen::kWoccSkyPushConstantsCameraXzDomeRadiusOffset);
        assert(skyReflection.module.reflection.pushConstantMembers[5].name
            == std::pmr::string("zenithBExposure"));
        assert(skyReflection.module.reflection.pushConstantMembers[5].offset
            == arp::shader::gen::kWoccSkyPushConstantsZenithBExposureOffset);

        std::cerr << "[ok] wocc_sky codegen contract: 144B struct, ColMajor viewProjection, "
                     "6 members, header/YAML/SPV all agree\n";
    }

    // ----------------------------------------------------------------
