        static_assert(sizeof(arp::shader::gen::WoccPostPushConstants) == 112, "");
        static_assert(arp::shader::gen::kWoccPostPushConstantsSize == 112, "");
        static_assert(arp::shader::gen::kWoccPostPushConstantsToneMappingExposureOffset == 0, "");
        static_assert(arp::shader::gen::kWoccPostPushConstantsTimeParamsOffset == 96, "");

