        // MRT (WoccPrevCamera UBO), so TAA carries NO float4x4. Assert NO
        // RowMajor/ColMajor SPV decoration and no row_major in source.
        static_assert(sizeof(arp::shader::gen::TaaPushConstants) == 64, "");
        static_assert(arp::shader::gen::kTaaPushConstantsSize == 64, "");
        static_assert(arp::shader::gen::kTaaPushConstantsTexelSizeOffset == 0, "");
        static_assert(arp::shader::gen::kTaaPushConstantsBlendParamsOffset == 16, "");
